cards.example:
resource "aws_instance" "api" {
  ami           = "ami-0abc123"
  instance_type = "t3.small"
  tags = { Name = "api-prod", Owner = "platform" }
}

terraform {
  backend "s3" {
    bucket         = "tf-state-prod"
    key            = "vpc/terraform.tfstate"
    dynamodb_table = "tf-locks"
    encrypt        = true
  }
}

# -/+ destroy and then create replacement
lifecycle {
  prevent_destroy = true
}

envs/
  stage/main.tf   -> module vpc { cidr = 10.10.0.0/16 }
  prod/main.tf    -> module vpc { cidr = 10.0.0.0/16 }
modules/vpc/

variable "instance_type" { default = "t3.small" }
locals { name_prefix = "${var.env}-api" }
output "alb_dns" { value = aws_lb.this.dns_name }

export TF_VAR_db_password=...   # секрет не в коде

terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.40" }
  }
}
